const items = $input.all();
const rows = items.map(item => item.json);

if (rows.length === 0) {
  return [{ json: { report: 'No data found in the CSV file.' } }];
}

const columns = Object.keys(rows[0]);
const totalRows = rows.length;
const totalColumns = columns.length;

const missingValues = {};

for (const column of columns) {
  missingValues[column] = rows.filter(row =>
    row[column] === null ||
    row[column] === undefined ||
    String(row[column]).trim() === ''
  ).length;
}

const duplicateRows = totalRows - new Set(
  rows.map(row => JSON.stringify(row))
).size;

// Helper function to calculate percentiles (Q1, Median, Q3)
function getPercentile(sortedArr, p) {
  if (sortedArr.length === 0) return 0;
  const index = (sortedArr.length - 1) * p;
  const lower = Math.floor(index);
  const upper = lower + 1;
  const weight = index - lower;
  if (upper >= sortedArr.length) return sortedArr[lower];
  return sortedArr[lower] * (1 - weight) + sortedArr[upper] * weight;
}

// Helper function to calculate mode
function getMode(arr) {
  const freq = {};
  let maxFreq = 0;
  for (const val of arr) {
    freq[val] = (freq[val] || 0) + 1;
    if (freq[val] > maxFreq) {
      maxFreq = freq[val];
    }
  }
  const modes = Object.keys(freq)
    .filter(key => freq[key] === maxFreq)
    .map(Number);

  if (modes.length === arr.length && arr.length > 1) {
    return 'No unique mode';
  }
  return modes.join(', ');
}

const numericalStatistics = {};

for (const column of columns) {
  const nonEmptyValues = rows
    .map(row => row[column])
    .filter(value => value !== null && value !== undefined && String(value).trim() !== '');

  const numericValues = nonEmptyValues
    .map(value => Number(value))
    .filter(value => !isNaN(value));

  // Treat as numerical column if >= 90% of non-empty values are numeric
  const isNumericalColumn =
    nonEmptyValues.length > 0 &&
    numericValues.length / nonEmptyValues.length >= 0.9;

  if (isNumericalColumn) {
    const sorted = [...numericValues].sort((a, b) => a - b);

    const count = sorted.length;
    const uniqueCount = new Set(sorted).size;
    const sum = sorted.reduce((a, b) => a + b, 0);
    const mean = sum / count;
    const min = sorted[0];
    const max = sorted[sorted.length - 1];

    const q1 = getPercentile(sorted, 0.25);
    const median = getPercentile(sorted, 0.50);
    const q3 = getPercentile(sorted, 0.75);
    const iqr = q3 - q1;
    const mode = getMode(sorted);

    numericalStatistics[column] = {
      count: count,
      unique: uniqueCount,
      mean: Number(mean.toFixed(2)),
      mode: mode,
      minimum: min,
      q1: Number(q1.toFixed(2)),
      median: Number(median.toFixed(2)),
      q3: Number(q3.toFixed(2)),
      iqr: Number(iqr.toFixed(2)),
      maximum: max
    };
  }
}

let report = `CSV DATA ANALYSIS REPORT\n\n`;
report += `Total Rows: ${totalRows}\n`;
report += `Total Columns: ${totalColumns}\n\n`;

report += `COLUMNS:\n`;
report += columns.join(', ') + '\n\n';

report += `MISSING VALUES:\n`;
for (const column of columns) {
  report += `${column}: ${missingValues[column]}\n`;
}

report += `\nDUPLICATE ROWS: ${duplicateRows}\n\n`;

report += `NUMERICAL STATISTICS:\n`;

if (Object.keys(numericalStatistics).length === 0) {
  report += 'No numerical columns detected.\n';
} else {
  for (const column of Object.keys(numericalStatistics)) {
    const stat = numericalStatistics[column];
    report += `\n--- ${column} ---\n`;
    report += `Count: ${stat.count}\n`;
    report += `Unique Values: ${stat.unique}\n`;
    report += `Mean: ${stat.mean}\n`;
    report += `Mode: ${stat.mode}\n`;
    report += `Minimum: ${stat.minimum}\n`;
    report += `Q1 (25%): ${stat.q1}\n`;
    report += `Median (50%): ${stat.median}\n`;
    report += `Q3 (75%): ${stat.q3}\n`;
    report += `IQR: ${stat.iqr}\n`;
    report += `Maximum: ${stat.maximum}\n`;
  }
}

return [{
  json: {
    total_rows: totalRows,
    total_columns: totalColumns,
    columns: columns,
    missing_values: missingValues,
    duplicate_rows: duplicateRows,
    numerical_statistics: numericalStatistics,
    report: report
  }
}];
